WITH cleaned AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, INITCAP(TRIM(txn_type)) AS txn_type_title, COALESCE(merchant, 'NONE') AS merchant_clean FROM transactions WHERE txn_time > TIMESTAMP '2024-05-10 14:00:00' AND merchant IS NOT NULL) SELECT *, LAG(amount, 1, 0) OVER (ORDER BY amount, id) AS prev_amount, AVG(amount) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS amount_avg_5, AVG(amount) OVER w_recent AS amount_avg_5_prior, ROW_NUMBER() OVER w_recent_2 AS event_seq, RANK() OVER (PARTITION BY account_id, txn_type ORDER BY amount DESC) AS amount_rank FROM cleaned WINDOW w_recent AS (ORDER BY txn_time, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING), w_recent_2 AS (PARTITION BY account_id ORDER BY txn_time, id);
